private fun referenceIcon(name: String, vararg paths: Pair<PathFillType, String>): ImageVector =
    ImageVector.Builder(name = name, defaultWidth = 24.dp, defaultHeight = 24.dp, viewportWidth = 24f, viewportHeight = 24f).apply {
        paths.forEach { (fillType, data) ->
            addPath(pathData = PathParser().parsePathString(data).toNodes(), fill = SolidColor(DuaVectorStroke), pathFillType = fillType)
        }
    }.build()
